import{_ as a,o as s,c as e,a5 as i}from"./chunks/framework.BjM_ivYE.js";const u=JSON.parse('{"title":"개발자 설정 가이드","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/guides/level-0/developers-guide.md","filePath":"ko/guides/level-0/developers-guide.md","lastUpdated":1790671199000}'),o={name:"ko/guides/level-0/developers-guide.md"};function n(d,t,l,r,h,p){return s(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="개발자-설정-가이드" tabindex="-1">개발자 설정 가이드 <a class="header-anchor" href="#개발자-설정-가이드" aria-label="Permalink to &quot;개발자 설정 가이드&quot;">​</a></h1><p><strong>목표:</strong> RBQ 저장소를 클론하고, 개발 환경을 갖춘 뒤, 시뮬레이터로 로봇 동작을 미리 검증합니다. 실제 하드웨어 테스트 전에 꼭 완료하세요.</p><div class="sb sb-required"><div class="sb-icon"><span class="sb-book" aria-hidden="true">📖</span></div><div class="sb-content"><p class="custom-block-title">필독 사항</p><p>실제 로봇에서 테스트하기 전에 안전 지침을 꼭 읽어두세요: <a href="/RBQ/ko/manual/safety/general-safety-warning-precautions">일반 안전 지침</a>.</p></div></div><h2 id="시스템-요구-사항" tabindex="-1">시스템 요구 사항 <a class="header-anchor" href="#시스템-요구-사항" aria-label="Permalink to &quot;시스템 요구 사항&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>요구 사항</th></tr></thead><tbody><tr><td>OS</td><td>Ubuntu 22.04 (x86-64)</td></tr><tr><td>CPU</td><td>Intel Core i7 12세대 이상</td></tr><tr><td>RAM</td><td>16 GB 이상</td></tr><tr><td>저장 공간</td><td>25 GB 여유 공간</td></tr><tr><td>조작 장치</td><td>키보드 (W/A/S/D, Q/E, 방향키) 또는 Logitech F710 게임패드</td></tr></tbody></table><h2 id="_1단계-저장소-클론" tabindex="-1">1단계. 저장소 클론 <a class="header-anchor" href="#_1단계-저장소-클론" aria-label="Permalink to &quot;1단계. 저장소 클론&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/RainbowRobotics/RBQ.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RBQ</span></span></code></pre></div><blockquote><p>모든 SDK 소스코드, 예제, 스크립트, 시뮬레이터 환경은 <code>RBQ/</code> 안에 있습니다.<br> 별도 언급이 없으면 이 디렉토리에서 명령을 실행하세요.</p></blockquote><blockquote><p><strong>참고:</strong> 사전 빌드된 바이너리는 <code>bin-x86_64/</code>(arm64는 <code>bin-aarch64/</code>)에 들어 있습니다. 시뮬레이터 실행이나 로봇 배포에 별도 빌드가 필요하지 않습니다.</p></blockquote><h2 id="_2단계-시뮬레이터-실행" tabindex="-1">2단계. 시뮬레이터 실행 <a class="header-anchor" href="#_2단계-시뮬레이터-실행" aria-label="Permalink to &quot;2단계. 시뮬레이터 실행&quot;">​</a></h2><p>시뮬레이터는 도커 안에서 실행됩니다. 도커 외에는 설치할 것이 없고, 도커가 없으면 스크립트가 설치를 제안합니다. 처음 실행할 때 이미지를 만드느라 몇 분 걸립니다. <a href="/RBQ/ko/software/simulator/mujoco.html">MuJoCo</a>를 참조하세요.</p><p>RBQ 제어 스택과 MuJoCo 물리 시뮬레이터를 한꺼번에 띄웁니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-gui</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 모션만</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-gui</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --vision</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 모션 + 비전 센서</span></span></code></pre></div><p>이 터미널에서 계속 실행되며, Ctrl-C 로 멈춥니다. 이 PC 에서 도커에 <code>sudo</code> 가 필요하면 비밀번호를 묻습니다. 입력하면 계속 진행됩니다.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">참고</p><p><code>--no-gui</code> 를 붙이십시오. 이 저장소에는 PC 에서 도는 제어 GUI 가 들어 있지 않습니다. 시뮬레이터는 실제 로봇과 똑같이 <strong>RBQ</strong> 앱으로 조종합니다.</p></div></div><h2 id="_3단계-rbq-앱으로-연결하고-로봇-일으키기" tabindex="-1">3단계. RBQ 앱으로 연결하고 로봇 일으키기 <a class="header-anchor" href="#_3단계-rbq-앱으로-연결하고-로봇-일으키기" aria-label="Permalink to &quot;3단계. RBQ 앱으로 연결하고 로봇 일으키기&quot;">​</a></h2><p><strong><a href="/RBQ/ko/manual/downloads/">다운로드</a></strong> 페이지에서 RBQ 데스크탑 앱을 설치한 뒤:</p><ol><li>시뮬레이터를 띄운 <strong>그 PC 에서</strong> 앱을 켭니다. 주변에 로봇망이 없으면 데스크탑 앱이 이 PC 의 MuJoCo 시뮬레이터를 스스로 찾아 붙습니다 — <a href="/RBQ/ko/manual/gui/connection.html">연결</a>을 참고하세요.</li><li>허브에서 <strong>컨트롤</strong>을 눌러 제어 홈을 엽니다.</li><li>초록색 <strong>자동 기동</strong> 버튼을 누르고, 창에서 <strong>자동 기동</strong>을 눌러 시퀀스가 <strong>완료</strong>로 바뀔 때까지 기다린 뒤 <strong>닫기</strong>를 누릅니다.</li><li>모션 카드의 <code>STAND</code> 를 눌러 로봇을 일으킵니다.</li></ol><p>이제 로봇이 명령을 받을 준비가 됐습니다. 조이스틱과 보행 제어는 <a href="/RBQ/ko/manual/gui/motion-commands.html">모션 명령</a>을 참고하세요.</p><h2 id="_4단계-실제-로봇에서-실행" tabindex="-1">4단계. 실제 로봇에서 실행 <a class="header-anchor" href="#_4단계-실제-로봇에서-실행" aria-label="Permalink to &quot;4단계. 실제 로봇에서 실행&quot;">​</a></h2><p>하드웨어 테스트 준비가 됐다면:</p><ol><li>로봇을 <a href="/RBQ/ko/guides/common/initial-pose.html">올바른 초기 자세</a>로 놓습니다.</li><li>기기를 로봇 Wi-Fi(<code>RBQ_xxxx</code>)에 연결합니다.</li><li>RBQ 앱을 켜고 로봇 목록에서 로봇을 고릅니다 — <a href="/RBQ/ko/manual/gui/connection.html">연결</a> 참고.</li><li><strong>컨트롤</strong> → <strong>자동 기동</strong> → <code>STAND</code> 순서로 누릅니다.</li></ol><p>방금 시뮬레이터에서 했던 것과 같은 절차입니다. 시뮬레이터에서 미리 익혀 두는 이유가 여기에 있습니다.</p><blockquote><p>실제 로봇에서 테스트하기 전에 시뮬레이션으로 모든 동작을 먼저 검증하는 걸 권장합니다.</p></blockquote><h2 id="_5단계-로봇-업데이트" tabindex="-1">5단계. 로봇 업데이트 <a class="header-anchor" href="#_5단계-로봇-업데이트" aria-label="Permalink to &quot;5단계. 로봇 업데이트&quot;">​</a></h2><p>로봇 소프트웨어는 앱의 <code>소프트웨어 업데이트</code> 화면에서 <strong><code>로봇 소프트웨어 전송</code></strong> 으로 갱신합니다. 전송이 끝나면 로봇이 곧바로 배포하고, 앱이 재부팅 여부를 묻습니다.</p><p><strong>→ <a href="/RBQ/ko/manual/gui/software-update.html">로봇 소프트웨어 업데이트</a></strong></p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>재시작 전에 로봇을 <strong>앉은 자세</strong>로 두고, 재시작이 끝날 때까지 움직이지 마세요. 바이너리와 스크립트 버전이 맞지 않으면 예상치 못한 동작이 생길 수 있습니다.</p></div></div><h2 id="상세-참고-문서" tabindex="-1">상세 참고 문서 <a class="header-anchor" href="#상세-참고-문서" aria-label="Permalink to &quot;상세 참고 문서&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>링크</th></tr></thead><tbody><tr><td>전체 가이드</td><td><a href="/RBQ/ko/software/developers-guide.html">개발자 가이드 (소프트웨어)</a></td></tr><tr><td>RBQ 앱 화면별 설명</td><td><a href="/RBQ/ko/manual/gui/introduction.html">RBQ 앱</a></td></tr><tr><td>시뮬레이션 환경</td><td><a href="/RBQ/ko/software/developers-guide.html#simulation">MuJoCo 시뮬레이션</a></td></tr><tr><td>개념 및 아키텍처</td><td><a href="/RBQ/ko/software/concept.html">Concept</a></td></tr></tbody></table>`,30)])])}const k=a(o,[["render",n]]);export{u as __pageData,k as default};
